import { useState, useTransition } from 'react';

const allItems = Array.from({ length: 5000 }, (_, index) => `Item ${index + 1}`);

export default function SearchList() {
  const [query, setQuery] = useState('');
  const [items, setItems] = useState(allItems);
  const [isPending, startTransition] = useTransition();

  function handleChange(value) {
    setQuery(value);
    startTransition(() => {
      setItems(allItems.filter((item) => item.toLowerCase().includes(value.toLowerCase())));
    });
  }

  return (
    <>
      <input value={query} onChange={(event) => handleChange(event.target.value)} />
      <p aria-live="polite">{isPending ? 'Updating…' : `${items.length} results`}</p>
      <ul>{items.slice(0, 20).map((item) => <li key={item}>{item}</li>)}</ul>
    </>
  );
}

